// Проверка подписи входящего вебхука и разбор сообщения.
//
// Без этой проверки вебхук открыт: кто узнал адрес, тот может прислать
// {phone, text} от имени любого водителя — и отметить этап чужого рейса.
// Платформа доверяет нашей подписи; мы обязаны доверять только провайдеру.
//
// Meta (WhatsApp Cloud API) подписывает тело так же, как RAHTIS:
// HMAC-SHA256 на App Secret, заголовок X-Hub-Signature-256 вида sha256=<hex>.
// Если провайдер другой — замените проверку на его схему, но не убирайте.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.WHATSAPP_APP_SECRET) SECRET = $vars.WHATSAPP_APP_SECRET; } catch (e) {}
if (!SECRET) throw new Error('WHATSAPP_APP_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;

// rawBody включён в узле Webhook: подпись обязана считаться от тех же
// байтов, которые прислал провайдер. Пересобранный JSON даст другую строку.
const raw = $json.body === undefined ? '' : (typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body));
const given = $json.headers['x-hub-signature-256'] || '';

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');

// Сравнение постоянного времени: обычное === выходит на первом несовпавшем
// байте, и подпись подбирается побайтово по времени ответа.
const a = Buffer.from(expected);
const b = Buffer.from(given);
const ok = a.length === b.length && crypto.timingSafeEqual(a, b);

let payload = {};
try { payload = typeof raw === 'string' && raw ? JSON.parse(raw) : ($json.body || {}); } catch (e) { payload = {}; }

// Разбор формата WhatsApp Cloud API. Запасные пути — для ручной проверки
// из curl и для провайдеров с плоским телом.
const msg = payload?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const phoneRaw = msg?.from || payload.phone || payload.from || '';
const text = msg?.text?.body || payload.text || payload.message || '';

// Только цифры — ровно так же нормализует база (app.phone_digits).
const phone = String(phoneRaw).replace(/\D/g, '');

return [{ json: { ok, phone, text } }];

// Подпись запроса к RAHTIS.
//
// Проверено на боевом эндпоинте: HMAC-SHA256 на DRIVER_WEBHOOK_SECRET от
// строки `${timestamp}.${body}`, заголовок x-rahtis-signature вида
// sha256=<hex>, окно 300 секунд.
//
// Тело уходит как raw: если дать узлу HTTP пересобрать JSON, подпись
// начнёт зависеть от порядка ключей и разойдётся с нашей.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.DRIVER_WEBHOOK_SECRET) SECRET = $vars.DRIVER_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('DRIVER_WEBHOOK_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;

const body = JSON.stringify({ phone: $json.phone });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');

return [{ json: { body, timestamp, signature, phone: $json.phone, text: $json.text } }];

// Запрос к Claude: понять водителя и решить, что делать.
//
// Модель отвечает одним из трёх: METKA:STEP:<роль> — водитель сообщил об
// этапе; METKA:ESCALATE — вопрос человеку; иначе — готовый ответ.
//
// Кроме этого у неё два инструмента, и они разной природы.
//
// eta считает платформа: тот же маршрутизатор с грузовым профилем, что
// считал километраж заказа. Число приходит оттуда, а не из головы
// модели, и разойтись с диспетчером поэтому не может.
//
// web_search работает на стороне Anthropic и нужен ровно для одного —
// часов работы и порядка въезда, которых в платформе нет и не будет.
// Список сайтов закрыт намеренно: без него на вопрос «во сколько
// открывается Вуосаари» находится форум пятилетней давности, и время
// оттуда звучит так же уверенно, как настоящее. Со списком модель либо
// находит ответ у оператора порта, либо не находит вовсе — и тогда
// честно отправляет вопрос человеку.
//
// Модель: claude-opus-5, effort low — водитель за рулём, нужна скорость.

const trips = $json.trips;
const src = $('Подпись: контекст').item.json;
const text = src.text;

// Сайты, которым можно верить про часы работы: операторы портов и
// паромные линии. Проверены поиском, а не взяты по памяти — домена,
// которого нет, поиск молча не замечает, и в ответе это не видно.
const SITES = [
  'portofhelsinki.fi',
  'haminakotka.com',
  'portofhanko.fi',
  'portofrauma.com',
  'portofnaantali.fi',
  'portofturku.fi',
  'portofpori.fi',
  'portofkokkola.fi',
  'ouluport.com',
  'kvarkenports.com',
  'euroports.fi',
  'satamaoperaattorit.fi',
  'finnlines.com',
  'tallink.com',
  'stenaline.com',
  'transfennica.com',
  'dfds.com',
];

const system = [
  'Ты — диспетчер-помощник платформы RAHTIS для водителя грузовика.',
  'Водитель за рулём: отвечай КОРОТКО, одним-двумя предложениями.',
  '',
  'Факты о рейсе бери ТОЛЬКО из данных ниже. Не выдумывай адреса, телефоны и время.',
  '',
  'Определи, что сделал водитель:',
  '1. СООБЩИЛ ОБ ЭТАПЕ (забрал, загрузился, выгрузился, сдал) — верни строго METKA:STEP:<роль>,',
  '   где роль одна из: PICKUP, DELIVERY, EXTRA_LOAD, EXTRA_UNLOAD, CONTINUATION, TRAILER_RETURN.',
  '   Роль бери из поля progress.next.role — водитель отмечает именно следующую точку.',
  '2. СПРОСИЛ по рейсу (где выгрузка, чей телефон, во сколько, нужна ли пломба) — ответь фактом.',
  '3. Вопрос спорный, про деньги или про повреждения — верни строго METKA:ESCALATE.',
  '',
  'ВАЖНО про единицу: haul_kind = CONTAINER означает КОНТЕЙНЕР, а не прицеп.',
  'Тогда trailer_plate — это номер контейнера по ISO 6346, а container_feet — его длина в футах.',
  'Называй вещи своими именами: «контейнер 20 футов MSCU1234561», не «прицеп».',
  'При haul_kind = TRAILER это полуприцеп и его регистрационный номер.',
  '',
  'ПЛОЩАДКИ: в guides лежат инструкции по портам и терминалам этого рейса.',
  'Адрес ворот бери оттуда: он точнее адреса точки, если они разошлись.',
  '',
  'ВРЕМЯ В ПУТИ («когда буду», «успею ли», «сколько ехать») — инструмент eta.',
  'Ему нужно, где водитель сейчас. Не сказал — спроси одним коротким вопросом.',
  'Своё число не придумывай и не складывай километры в уме: считает маршрутизатор,',
  'тот же, что у диспетчера, с грузовым профилем и пробками.',
  '',
  'ЧАСЫ РАБОТЫ И ПОРЯДОК ВЪЕЗДА: в платформе их нет — ищи инструментом web_search.',
  'Нашёл — назови время И сайт, откуда оно взято. Без источника время не называй вовсе.',
  'Не нашёл, нашёл противоречие или сайт молчит — верни METKA:ESCALATE, а не догадку.',
  'Водитель поедет по твоему ответу: опоздание к закрытым воротам стоит суток.',
  '',
  'РЕЖИМ ТРУДА И ОТДЫХА (ЕС 561/2006, AETR). Правила постоянные, вот они:',
  '- 4,5 часа езды — перерыв 45 минут; его можно разбить на 15 и затем 30, в этом порядке.',
  '- Езда за сутки 9 часов, дважды в неделю допускается 10.',
  '- Езда за неделю 56 часов, за две недели подряд 90.',
  '- Суточный отдых 11 часов; трижды между недельными отдыхами допускается 9.',
  '- Недельный отдых 45 часов; через неделю допускается 24 с последующей компенсацией.',
  'НО: сколько водитель уже отъездил сегодня, платформа НЕ знает — тахографа у неё нет.',
  'Поэтому никогда не говори «у тебя осталось столько-то» и не подтверждай соблюдение режима.',
  'Объясняй правило и отсылай к тахографу.',
  '',
  'Язык ответа — тот же, на котором написал водитель.',
  '',
  'ДАННЫЕ РЕЙСОВ:',
  JSON.stringify(trips),
].join('\n');

const tools = [
  {
    name: 'eta',
    description:
      'Сколько ехать до следующей точки рейса и успевает ли водитель к назначенному времени. '
      + 'Считает маршрутизатор платформы: грузовой профиль, пробки. Рейс берётся по номеру телефона.',
    input_schema: {
      type: 'object',
      properties: {
        origin: {
          type: 'string',
          description: 'Где водитель сейчас, его словами: город, порт, заправка, развязка',
        },
      },
      required: ['origin'],
    },
  },
  {
    type: 'web_search_20260209',
    name: 'web_search',
    max_uses: 3,
    allowed_domains: SITES,
  },
];

const state = {
  phone: src.phone,
  system,
  tools,
  iterations: 0,
  messages: [{ role: 'user', content: text }],
};

const payload = {
  model: 'claude-opus-5',
  max_tokens: 1024,
  output_config: { effort: 'low' },
  system,
  tools,
  // Один инструмент за круг: цикл ниже возвращает один результат, и два
  // вызова разом оставили бы второй без ответа.
  tool_choice: { type: 'auto', disable_parallel_tool_use: true },
  messages: state.messages,
};

return [{ json: { __state: state, payload: JSON.stringify(payload) } }];

// Что модель решила на этом круге.
//
// Состояние берётся у предыдущего узла, а не из ответа HTTP: узел HTTP
// заменяет элемент целиком, и всё, что мы к нему прикрепили, сюда не
// доезжает. На первом круге состояние даёт сборщик запроса, на
// следующих — последний прогон «Добавить результат».
//
// Ответ ассистента кладётся в историю ЦЕЛИКОМ, вместе с блоками
// tool_use и результатами поиска: следующий запрос обязан содержать тот
// же tool_use, к которому мы вернём tool_result, иначе API не свяжет их.

let prev = null;
try {
  const added = $('Добавить результат').all();
  if (added.length) prev = added[added.length - 1].json.__state;
} catch (e) {
  prev = null;
}
if (!prev) prev = $('Собрать запрос к Claude').first().json.__state;

const res = $json;

if (res.error || !Array.isArray(res.content)) {
  const why = res.error ? (res.error.message || JSON.stringify(res.error)) : 'ответ модели не разобран';
  return [{ json: { decision: 'ERROR', reply: 'Palvelu ei vastaa. / Служба не отвечает.', detail: String(why).slice(0, 300) } }];
}

const messages = prev.messages.concat([{ role: 'assistant', content: res.content }]);
const next = Object.assign({}, prev, { messages });

// Потолок на круги. Трёх хватает на «посчитай время» и «найди часы
// работы»; без потолка модель, зациклившаяся на поиске, молотила бы,
// пока водитель ждёт ответа.
const overLimit = next.iterations >= 3;

// Инструмент платформы. Поиск сюда не попадает: он исполняется на
// стороне Anthropic и приходит уже с результатом.
const toolUse = res.content.find((b) => b.type === 'tool_use');

// Круги кончились, а модель всё ещё тянется к инструменту: ответа у
// неё нет. Водителю уйдёт обрывок фразы вроде «сейчас посмотрю», если
// просто взять текст этого круга, — поэтому вопрос идёт человеку.
if (res.stop_reason === 'tool_use' && toolUse && overLimit) {
  return [{ json: { __state: next, decision: 'ESCALATE', reply: 'METKA:ESCALATE' } }];
}

if (res.stop_reason === 'tool_use' && toolUse && !overLimit) {
  return [{ json: {
    __state: next,
    decision: 'TOOL',
    tool: toolUse.name,
    tool_use_id: toolUse.id,
    args: toolUse.input || {},
  } }];
}

// Поиск не уложился в один ответ: продолжаем тот же разговор, ничего
// не добавляя от себя. Без этой ветки незаконченный поиск выглядел бы
// готовым ответом — и водителю уходило бы пустое сообщение.
if (res.stop_reason === 'pause_turn' && !overLimit) {
  return [{ json: { __state: next, decision: 'CONTINUE' } }];
}

const reply = res.content.filter((b) => b.type === 'text').map((b) => b.text).join('').trim();

let decision = 'ANSWER';
let role = '';

if (reply.startsWith('METKA:STEP:')) {
  decision = 'STEP';
  role = reply.slice('METKA:STEP:'.length).trim().split(/\s/)[0];
} else if (reply.includes('METKA:ESCALATE')) {
  decision = 'ESCALATE';
}

return [{ json: { __state: next, decision, role, reply } }];

// Подпись отметки этапа.
//
// expect — роль точки со слов водителя. Платформа сверит её со следующей
// непройденной точкой и откажет, если не совпало: агент, неверно понявший
// фразу, не должен продвигать рейс.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.DRIVER_WEBHOOK_SECRET) SECRET = $vars.DRIVER_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('DRIVER_WEBHOOK_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;
const phone = $('Подпись: контекст').item.json.phone;

const body = JSON.stringify({ phone, expect: $json.role });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');

return [{ json: { body, timestamp, signature } }];

// Подпись эскалации.
//
// Вопрос уходит в ту же очередь, которую оператор читает в админке.
// Работает независимо от того, есть ли у водителя активный рейс.

const crypto = require('crypto');

// Секрет для подписи.
//
// $env в узлах Code на n8n Cloud закрыт наглухо: с версии 2.0
// N8N_BLOCK_ENV_ACCESS_IN_NODE по умолчанию true, и на облаке этот
// переключатель недоступен. Поэтому секрет берётся из переменных n8n
// ($vars — планы Pro и Enterprise Cloud).
//
// Если у вас Starter, где переменных нет, впишите значение в SECRET
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.DRIVER_WEBHOOK_SECRET) SECRET = $vars.DRIVER_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('DRIVER_WEBHOOK_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;
const src = $('Проверить подпись провайдера').item.json;

const body = JSON.stringify({ phone: src.phone, question: src.text });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');

return [{ json: { body, timestamp, signature } }];

// Что сказать водителю.
//
// Отказ платформы — штатный путь, а не исключение: «точка уже пройдена»,
// «роль не совпала», «рейс уже не идёт». Все три приходят кодом 55000 с
// понятным текстом в detail, и водителю надо показать именно его, а не
// общее «не получилось».

const src = $json;
let reply;

if (src.ok === true) {
  reply = 'Kuittaus vastaanotettu ✅ / Отметка принята ✅';
} else if (src.error) {
  // detail пишет та же функция базы, которая отказала: она знает почему.
  reply = src.detail || 'Ei onnistunut. / Не получилось.';
} else if (src.decision === 'ANSWER' || src.reply) {
  reply = src.reply;
} else {
  reply = 'Selvä. / Принято.';
}

return [{ json: { reply } }];

// Что сказать водителю, когда вопрос ушёл человеку.
//
// Прежде здесь стояло «передал диспетчеру» — и это был тупик: какому
// диспетчеру, своему или чужому, и куда придёт ответ, водитель не знал.
// Вопрос уходит оператору платформы, в очередь, которую он читает в
// админке, и ответ вернётся в эту же переписку. Так и сказано.

const src = $json;
const reply = src.ok === true
  ? 'Välitin kysymyksen RAHTIS-operaattorille (Aivomaa Oy). Vastaus tulee tähän samaan keskusteluun.'
    + ' / Передал вопрос оператору платформы RAHTIS (Aivomaa Oy). Ответ придёт сюда же.'
  : (src.detail || 'Kysymystä ei saatu välitettyä. / Вопрос передать не удалось.');
return [{ json: { reply } }];

// Неверная подпись провайдера — тупик, и намеренно.
//
// Прежде эта ветка отвечала водителю текстом. С настоящей отправкой
// такой ответ означал бы, что любой, кто узнал адрес вебхука, может
// заставить наш номер написать произвольному человеку: подпись не
// сошлась, а номер взят из того же неподписанного тела.
//
// Мете при этом уже возвращён код 200 — узел вебхука отвечает сразу,
// не дожидаясь ветвления. Молчание здесь и есть правильный ответ.
//
// Причина видна в журнале выполнений n8n; наружу она не выходит, чтобы
// не подсказывать подбирающему, что именно не сошлось.
return [{ json: { refused: true } }];

// Подтверждение подписки на вебхук.
//
// Перед тем как слать события, Мета делает GET с hub.mode,
// hub.verify_token и hub.challenge и ждёт обратно значение challenge
// голым текстом. Без этого ответа подписку просто не создать — узел
// на POST для этого не годится, он на GET не отвечает.
//
// Токен здесь свой, не тот, которым подписываются сообщения: он
// нужен один раз при подключении и живёт отдельно, чтобы его можно
// было показать тому, кто настраивает, не отдавая App Secret.

// Значение берётся из переменных n8n ($vars — планы Pro и Enterprise
// Cloud): $env в узлах Code на облаке закрыт наглухо с версии 2.0.
//
// Если у вас Starter, где переменных нет, впишите значение в VALUE
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let VALUE = '';
try { if (typeof $vars !== 'undefined' && $vars.WHATSAPP_VERIFY_TOKEN) VALUE = $vars.WHATSAPP_VERIFY_TOKEN; } catch (e) {}
if (!VALUE) throw new Error('WHATSAPP_VERIFY_TOKEN ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v VALUE.');

const q = $json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === VALUE;

return [{ json: { ok, challenge: q['hub.challenge'] || '' } }];

// Сообщение водителю.
//
// Прежде ответ возвращался телом вебхука, и это не работало вовсе:
// Мете тело ответа не нужно, ей нужен код 200. Сообщение доходит
// только отдельным вызовом Graph API.
//
// Номер берётся из проверенного входящего, а не из тела запроса: на
// ветке с неверной подписью мы сюда не приходим вовсе, и наш номер
// нельзя заставить написать произвольному человеку.

// Значение берётся из переменных n8n ($vars — планы Pro и Enterprise
// Cloud): $env в узлах Code на облаке закрыт наглухо с версии 2.0.
//
// Если у вас Starter, где переменных нет, впишите значение в VALUE
// ниже. Оно останется видимым каждому, у кого есть доступ в n8n, —
// это плата за отсутствие хранилища секретов на этом тарифе.
let VALUE = '';
try { if (typeof $vars !== 'undefined' && $vars.WHATSAPP_PHONE_ID) VALUE = $vars.WHATSAPP_PHONE_ID; } catch (e) {}
if (!VALUE) throw new Error('WHATSAPP_PHONE_ID ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v VALUE.');
const phoneId = VALUE;

const to = $('Проверить подпись провайдера').item.json.phone;
const reply = $json.reply;

return [{ json: { phoneId, to, reply } }];

// Подпись расчёта времени в пути.
//
// Телефон берётся из проверенного входящего, а не из того, что назвала
// модель: рейс на платформе выводится из номера, и номер обязан быть
// тем же, чью подпись мы проверили.

const crypto = require('crypto');

let SECRET = '';
try { if (typeof $vars !== 'undefined' && $vars.DRIVER_WEBHOOK_SECRET) SECRET = $vars.DRIVER_WEBHOOK_SECRET; } catch (e) {}
if (!SECRET) throw new Error('DRIVER_WEBHOOK_SECRET ne zadan: sozdaite peremennuyu v n8n ili vpishite znachenie v SECRET.');
const secret = SECRET;

const st = $json.__state;
const phone = $('Подпись: контекст').item.json.phone;
const origin = String(($json.args && $json.args.origin) || '').slice(0, 120);

const body = JSON.stringify({ phone, origin });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');

return [{ json: { body, timestamp, signature, __state: st, tool_use_id: $json.tool_use_id } }];

// Результат инструмента обратно в разговор.
//
// Отказ тоже возвращается модели — блоком с is_error, а не молчанием.
// «Не понял, где ты находишься» это ответ, который модель должна
// пересказать водителю и переспросить, а не повод оборвать разговор.

const runs = $('Подпись: время в пути').all();
const signedRun = runs[runs.length - 1].json;
const st = signedRun.__state;
const res = $json;

const isError = Boolean(res.error);
const content = isError
  ? String(res.error) + (res.detail ? ': ' + res.detail : '')
  : JSON.stringify(res);

const messages = st.messages.concat([{
  role: 'user',
  content: [{
    type: 'tool_result',
    tool_use_id: signedRun.tool_use_id,
    content,
    is_error: isError,
  }],
}]);

const next = Object.assign({}, st, { messages, iterations: st.iterations + 1 });

return [{ json: { __state: next, payload: JSON.stringify({
  model: 'claude-opus-5',
  max_tokens: 1024,
  output_config: { effort: 'low' },
  system: next.system,
  tools: next.tools,
  tool_choice: { type: 'auto', disable_parallel_tool_use: true },
  messages: next.messages,
}) } }];

// Поиск не уложился в один ответ.
//
// Модель возвращает stop_reason = pause_turn, когда серверный поиск ещё
// идёт. Продолжение — это тот же разговор без единого нового слова от
// нас: история уже содержит незаконченный ответ ассистента, и API
// доводит его сам.

const st = $json.__state;
const next = Object.assign({}, st, { iterations: st.iterations + 1 });

return [{ json: { __state: next, payload: JSON.stringify({
  model: 'claude-opus-5',
  max_tokens: 1024,
  output_config: { effort: 'low' },
  system: next.system,
  tools: next.tools,
  tool_choice: { type: 'auto', disable_parallel_tool_use: true },
  messages: next.messages,
}) } }];
